#!/usr/bin/env python3
"""Evaluate the native full-OCR driver on a project metadata-backed dataset.

The generated images are intentionally supplied at runtime. They are not part
of the repository or release packages. Ground-truth lines are matched to
native OCR lines by one-to-one greedy IoU matching because metadata line order
is not an OCR reading-order contract.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import re
import subprocess
import sys
import tempfile
import unicodedata
from collections import defaultdict
from pathlib import Path
from typing import Any

from PIL import Image


FLOAT_RE = r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?"
HEADER_RE = re.compile(r"^lines=(?P<count>\d+)\s")
LINE_RE = re.compile(
    rf"^(?P<index>\d+)\s+text=(?P<text>.*?)\s+"
    rf"rec=(?P<rec>{FLOAT_RE})\s+det=(?P<det>{FLOAT_RE})\s+"
    rf"cls=(?P<cls_label>-?\d+)/(?P<cls_score>{FLOAT_RE})\s+"
    rf"rotate=(?P<rotation>-?\d+)\s+\[(?P<box>.*)\]\s*$"
)
POINT_RE = re.compile(rf"\(({FLOAT_RE})\s*,\s*({FLOAT_RE})\)")


def configure_utf8_output() -> None:
    for stream in (sys.stdout, sys.stderr):
        reconfigure = getattr(stream, "reconfigure", None)
        if reconfigure is not None:
            reconfigure(encoding="utf-8", errors="backslashreplace")


def normalize_text(value: str) -> str:
    return unicodedata.normalize("NFC", value.replace("\r\n", "\n"))


def edit_distance(expected: str, actual: str) -> int:
    previous = list(range(len(actual) + 1))
    for row, expected_char in enumerate(expected, 1):
        current = [row]
        for column, actual_char in enumerate(actual, 1):
            current.append(
                min(
                    current[-1] + 1,
                    previous[column] + 1,
                    previous[column - 1] + (expected_char != actual_char),
                )
            )
        previous = current
    return previous[-1]


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def require_mapping(value: Any, label: str) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError(f"{label} must be an object")
    return value


def read_dataset(dataset: Path) -> tuple[Path, dict[str, Any], list[str]]:
    dataset = dataset.resolve()
    manifest_path = dataset / "metadata.json" if dataset.is_dir() else dataset
    manifest_path = manifest_path.resolve()
    if not manifest_path.is_file():
        raise FileNotFoundError(f"dataset manifest not found: {manifest_path}")
    image_root = manifest_path.parent
    manifest = require_mapping(
        json.loads(manifest_path.read_text(encoding="utf-8")), "dataset manifest"
    )
    if manifest.get("version") != 1:
        raise ValueError("unsupported project dataset metadata version")
    generator = require_mapping(manifest.get("generator"), "dataset generator")
    if generator.get("name") != "lw.PPOCR.C":
        raise ValueError("dataset was not generated by lw.PPOCR.C")
    if generator.get("tool") != "tools/generate_ocr_dataset.py":
        raise ValueError("dataset generator tool is not supported")
    if not isinstance(generator.get("text_pool_sha256"), str):
        raise ValueError("dataset generator lacks text pool hash")
    images = manifest.get("images")
    if not isinstance(images, list) or not images:
        raise ValueError("dataset manifest images must be a non-empty array")

    warnings: list[str] = []
    seen: set[str] = set()
    for image in images:
        item = require_mapping(image, "dataset image")
        required = {"file", "width", "height", "sha256", "lines"}
        missing = sorted(required - item.keys())
        if missing:
            raise ValueError(f"dataset image is missing keys: {missing}")
        relative = Path(str(item["file"]))
        if relative.is_absolute() or ".." in relative.parts:
            raise ValueError(f"dataset image escapes dataset root: {item['file']}")
        relative_key = relative.as_posix()
        if relative_key in seen:
            raise ValueError(f"duplicate dataset image: {relative_key}")
        seen.add(relative_key)
        image_path = (image_root / relative).resolve()
        try:
            image_path.relative_to(image_root)
        except ValueError as exception:
            raise ValueError(f"dataset image escapes dataset root: {item['file']}") from exception
        if not image_path.is_file():
            raise FileNotFoundError(f"dataset image not found: {relative_key}")
        actual_hash = sha256_file(image_path)
        if actual_hash.lower() != str(item["sha256"]).lower():
            raise ValueError(f"dataset image SHA-256 mismatch: {relative_key}")
        with Image.open(image_path) as image_object:
            actual_size = image_object.size
        declared_size = (int(item["width"]), int(item["height"]))
        if actual_size != declared_size:
            raise ValueError(
                f"dataset image dimensions mismatch: {relative_key}: "
                f"{actual_size} != {declared_size}"
            )
        for line_index, line in enumerate(item["lines"]):
            line_mapping = require_mapping(line, f"{relative_key} line {line_index}")
            if "text" not in line_mapping or "bbox" not in line_mapping:
                raise ValueError(f"{relative_key} line {line_index} lacks text/bbox")
            if not isinstance(line_mapping["bbox"], list) or len(line_mapping["bbox"]) != 4:
                raise ValueError(f"{relative_key} line {line_index} bbox must have four values")
            if not str(line_mapping["text"]):
                raise ValueError(f"{relative_key} line {line_index} has empty text")
            x1, y1, x2, y2 = (float(value) for value in line_mapping["bbox"])
            if x1 < 0 or y1 < 0 or x2 > declared_size[0] or y2 > declared_size[1]:
                warnings.append(f"bbox outside image bounds: {relative_key} line {line_index}")
            if x1 >= x2 or y1 >= y2:
                raise ValueError(f"{relative_key} line {line_index} bbox is empty")
    return manifest_path, manifest, warnings


def clamp_bbox(box: list[float], width: int, height: int) -> tuple[float, float, float, float]:
    x1, y1, x2, y2 = box
    return (
        max(0.0, min(float(width), x1)),
        max(0.0, min(float(height), y1)),
        max(0.0, min(float(width), x2)),
        max(0.0, min(float(height), y2)),
    )


def points_bbox(points: list[tuple[float, float]]) -> tuple[float, float, float, float]:
    if len(points) != 4:
        raise ValueError("native OCR box must contain four points")
    xs = [point[0] for point in points]
    ys = [point[1] for point in points]
    return min(xs), min(ys), max(xs), max(ys)


def bbox_iou(first: tuple[float, float, float, float], second: tuple[float, float, float, float]) -> float:
    ix1 = max(first[0], second[0])
    iy1 = max(first[1], second[1])
    ix2 = min(first[2], second[2])
    iy2 = min(first[3], second[3])
    intersection = max(0.0, ix2 - ix1) * max(0.0, iy2 - iy1)
    first_area = max(0.0, first[2] - first[0]) * max(0.0, first[3] - first[1])
    second_area = max(0.0, second[2] - second[0]) * max(0.0, second[3] - second[1])
    union = first_area + second_area - intersection
    return intersection / union if union > 0.0 else 0.0


def parse_native_output(stdout: str) -> tuple[int | None, list[dict[str, Any]]]:
    declared_count: int | None = None
    lines: list[dict[str, Any]] = []
    for raw_line in stdout.splitlines():
        header = HEADER_RE.match(raw_line)
        if header:
            declared_count = int(header.group("count"))
            continue
        match = LINE_RE.match(raw_line)
        if not match:
            if raw_line and re.match(r"^\d+\s+text=", raw_line):
                raise ValueError(f"unparseable native OCR line: {raw_line}")
            continue
        points = [
            (float(point.group(1)), float(point.group(2)))
            for point in POINT_RE.finditer(match.group("box"))
        ]
        lines.append(
            {
                "index": int(match.group("index")),
                "text": normalize_text(match.group("text")),
                "rec_score": float(match.group("rec")),
                "det_score": float(match.group("det")),
                "cls_label": int(match.group("cls_label")),
                "cls_score": float(match.group("cls_score")),
                "rotation": int(match.group("rotation")),
                "box": points_bbox(points),
            }
        )
    if declared_count is not None and declared_count != len(lines):
        raise ValueError(
            f"native OCR declared {declared_count} lines but emitted {len(lines)}"
        )
    return declared_count, lines


def match_lines(
    ground_truth: list[tuple[float, float, float, float]],
    predicted: list[dict[str, Any]],
    threshold: float,
) -> list[tuple[int, int, float]]:
    candidates = [
        (bbox_iou(gt_box, prediction["box"]), gt_index, prediction_index)
        for gt_index, gt_box in enumerate(ground_truth)
        for prediction_index, prediction in enumerate(predicted)
    ]
    candidates.sort(key=lambda item: (-item[0], item[1], item[2]))
    used_gt: set[int] = set()
    used_predictions: set[int] = set()
    matches: list[tuple[int, int, float]] = []
    for iou, gt_index, prediction_index in candidates:
        if iou < threshold or gt_index in used_gt or prediction_index in used_predictions:
            continue
        used_gt.add(gt_index)
        used_predictions.add(prediction_index)
        matches.append((gt_index, prediction_index, iou))
    return matches


def finite_metric(value: float) -> float:
    return float(value) if math.isfinite(value) else 0.0


def new_line_metric() -> dict[str, Any]:
    return {
        "ground_truth_lines": 0,
        "matched_lines": 0,
        "exact_lines": 0,
        "iou_sum": 0.0,
        "reference_characters_on_matches": 0,
        "edit_distance_on_matches": 0,
    }


def summarize_line_metrics(raw: dict[str, Any]) -> dict[str, Any]:
    ground_truth = int(raw["ground_truth_lines"])
    matched = int(raw["matched_lines"])
    exact = int(raw["exact_lines"])
    characters = int(raw["reference_characters_on_matches"])
    distance = int(raw["edit_distance_on_matches"])
    return {
        "ground_truth_lines": ground_truth,
        "matched_lines": matched,
        "missing_lines": ground_truth - matched,
        "exact_lines": exact,
        "detection_recall": matched / ground_truth if ground_truth else 0.0,
        "mean_matched_iou": raw["iou_sum"] / matched if matched else 0.0,
        "exact_reference_line_rate": exact / ground_truth if ground_truth else 0.0,
        "matched_exact_line_rate": exact / matched if matched else 0.0,
        "reference_characters_on_matches": characters,
        "edit_distance_on_matches": distance,
        "cer_on_matched_lines": distance / characters if characters else 0.0,
    }


def evaluate_image(
    image_path: Path,
    image_record: dict[str, Any],
    driver: Path,
    detector: Path,
    classifier: Path,
    recognizer: Path,
    dictionary: Path,
    rec_max_width: int,
    iou_threshold: float,
    temporary: Path,
    timeout_seconds: int,
) -> dict[str, Any]:
    with Image.open(image_path) as source:
        rgb = source.convert("RGB")
        ppm_path = temporary / f"{image_path.stem}.ppm"
        rgb.save(ppm_path, format="PPM")
        width, height = rgb.size
    completed = subprocess.run(
        [
            str(driver),
            str(detector),
            str(classifier),
            str(recognizer),
            str(dictionary),
            str(ppm_path),
            str(rec_max_width),
        ],
        cwd=driver.parent,
        check=False,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        timeout=timeout_seconds,
    )
    if completed.returncode != 0:
        raise RuntimeError(
            f"OCR failed for {image_path.name} with exit code {completed.returncode}: "
            f"{completed.stdout}\n{completed.stderr}"
        )
    declared_count, predicted = parse_native_output(completed.stdout)
    ground_truth_boxes = [
        clamp_bbox(
            [float(value) for value in line["bbox"]],
            width,
            height,
        )
        for line in image_record["lines"]
    ]
    matches = match_lines(ground_truth_boxes, predicted, iou_threshold)
    exact_lines = 0
    reference_characters = 0
    distance = 0
    mismatch_details: list[dict[str, Any]] = []
    line_results: list[dict[str, Any]] = [
        {
            "category": str(line.get("category", "uncategorized")),
            "orientation_degrees": int(line.get("orientation_degrees", 0)),
            "matched": False,
            "exact": False,
            "iou": 0.0,
            "reference_characters": 0,
            "edit_distance": 0,
        }
        for line in image_record["lines"]
    ]
    for gt_index, prediction_index, iou in matches:
        expected = normalize_text(str(image_record["lines"][gt_index]["text"]))
        actual = predicted[prediction_index]["text"]
        line_distance = edit_distance(expected, actual)
        reference_characters += len(expected)
        distance += line_distance
        exact = expected == actual
        exact_lines += int(exact)
        line_results[gt_index].update(
            {
                "matched": True,
                "exact": exact,
                "iou": finite_metric(iou),
                "reference_characters": len(expected),
                "edit_distance": line_distance,
            }
        )
        if not exact:
            mismatch_details.append(
                {
                    "ground_truth_index": gt_index,
                    "prediction_index": prediction_index,
                    "iou": finite_metric(iou),
                    "expected": expected,
                    "actual": actual,
                }
            )
    matched = len(matches)
    missing = len(ground_truth_boxes) - matched
    extra = len(predicted) - matched
    return {
        "file": image_record["file"],
        "width": width,
        "height": height,
        "ground_truth_lines": len(ground_truth_boxes),
        "predicted_lines": len(predicted),
        "matched_lines": matched,
        "missing_lines": missing,
        "extra_lines": extra,
        "declared_prediction_lines": declared_count,
        "mean_matched_iou": finite_metric(
            sum(item[2] for item in matches) / matched if matched else 0.0
        ),
        "exact_lines": exact_lines,
        "reference_characters": reference_characters,
        "edit_distance": distance,
        "cer_on_matched_lines": distance / reference_characters if reference_characters else 0.0,
        "mismatch_details": mismatch_details,
        "line_results": line_results,
    }


def aggregate_core(results: list[dict[str, Any]], total_gt_lines: int) -> dict[str, Any]:
    predicted = sum(item["predicted_lines"] for item in results)
    matched = sum(item["matched_lines"] for item in results)
    missing = sum(item["missing_lines"] for item in results)
    extra = sum(item["extra_lines"] for item in results)
    exact = sum(item["exact_lines"] for item in results)
    reference_characters = sum(item["reference_characters"] for item in results)
    distance = sum(item["edit_distance"] for item in results)
    ious = [item["mean_matched_iou"] for item in results if item["matched_lines"]]
    precision = matched / predicted if predicted else 0.0
    recall = matched / total_gt_lines if total_gt_lines else 0.0
    f1 = 2.0 * precision * recall / (precision + recall) if precision + recall else 0.0
    return {
        "ground_truth_lines": total_gt_lines,
        "predicted_lines": predicted,
        "matched_lines": matched,
        "missing_lines": missing,
        "extra_lines": extra,
        "detection_precision": precision,
        "detection_recall": recall,
        "detection_f1": f1,
        "mean_matched_iou": sum(ious) / len(ious) if ious else 0.0,
        "exact_lines": exact,
        "exact_reference_line_rate": exact / total_gt_lines if total_gt_lines else 0.0,
        "matched_exact_line_rate": exact / matched if matched else 0.0,
        "reference_characters_on_matches": reference_characters,
        "edit_distance_on_matches": distance,
        "cer_on_matched_lines": distance / reference_characters if reference_characters else 0.0,
    }


def aggregate_line_groups(
    results: list[dict[str, Any]], field: str
) -> dict[str, dict[str, Any]]:
    grouped: dict[str, dict[str, Any]] = defaultdict(new_line_metric)
    for result in results:
        for line in result["line_results"]:
            key = str(line[field])
            raw = grouped[key]
            raw["ground_truth_lines"] += 1
            if not line["matched"]:
                continue
            raw["matched_lines"] += 1
            raw["iou_sum"] += float(line["iou"])
            raw["reference_characters_on_matches"] += int(line["reference_characters"])
            raw["edit_distance_on_matches"] += int(line["edit_distance"])
            raw["exact_lines"] += int(line["exact"])
    return {key: summarize_line_metrics(grouped[key]) for key in sorted(grouped)}


def aggregate(results: list[dict[str, Any]], total_gt_lines: int) -> dict[str, Any]:
    summary = aggregate_core(results, total_gt_lines)
    canvas_groups: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for result in results:
        canvas_groups[f"{result['width']}x{result['height']}"].append(result)
    summary["groups"] = {
        "category": aggregate_line_groups(results, "category"),
        "orientation_degrees": aggregate_line_groups(results, "orientation_degrees"),
        "canvas": {
            key: aggregate_core(items, sum(item["ground_truth_lines"] for item in items))
            for key, items in sorted(canvas_groups.items())
        },
    }
    return summary


def main() -> int:
    configure_utf8_output()
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--dataset", type=Path, required=True)
    parser.add_argument("--driver", type=Path, required=True)
    parser.add_argument("--detector", type=Path, required=True)
    parser.add_argument("--classifier", type=Path, required=True)
    parser.add_argument("--recognizer", type=Path, required=True)
    parser.add_argument("--dictionary", type=Path, required=True)
    parser.add_argument("--model-name", default="project-dataset")
    parser.add_argument("--rec-max-width", type=int, choices=(192, 320, 480, 640, 960), default=960)
    parser.add_argument("--iou-threshold", type=float, default=0.30)
    parser.add_argument("--limit", type=int)
    parser.add_argument("--start", type=int, default=0)
    parser.add_argument("--timeout-seconds", type=int, default=180)
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()
    if not 0.0 < args.iou_threshold <= 1.0:
        raise SystemExit("--iou-threshold must be in (0, 1]")
    if args.limit is not None and args.limit <= 0:
        raise SystemExit("--limit must be positive")
    if args.start < 0:
        raise SystemExit("--start must be non-negative")
    if args.timeout_seconds <= 0:
        raise SystemExit("--timeout-seconds must be positive")
    for path in (args.driver, args.detector, args.classifier, args.recognizer, args.dictionary):
        if not path.is_file():
            raise SystemExit(f"required OCR input does not exist: {path}")
    manifest_path, manifest, warnings = read_dataset(args.dataset)
    selected_images = manifest["images"][args.start :]
    if args.limit is not None:
        selected_images = selected_images[: args.limit]
    if not selected_images:
        raise SystemExit("dataset selection is empty")
    image_root = manifest_path.parent
    total_gt_lines = sum(len(item["lines"]) for item in selected_images)
    results: list[dict[str, Any]] = []
    with tempfile.TemporaryDirectory(prefix="lw-project-ocr-") as directory:
        temporary = Path(directory)
        for index, image_record in enumerate(selected_images):
            print(f"[project-ocr] {index + 1}/{len(selected_images)} {image_record['file']}")
            results.append(
                evaluate_image(
                    image_root / str(image_record["file"]),
                    image_record,
                    args.driver.resolve(),
                    args.detector.resolve(),
                    args.classifier.resolve(),
                    args.recognizer.resolve(),
                    args.dictionary.resolve(),
                    args.rec_max_width,
                    args.iou_threshold,
                    temporary,
                    args.timeout_seconds,
                )
            )
    report = {
        "schema_version": 1,
        "status": "ok",
        "model": args.model_name,
        "rec_max_width": args.rec_max_width,
        "iou_matching_threshold": args.iou_threshold,
        "dataset": {
            "manifest": manifest_path.name,
            "manifest_sha256": sha256_file(manifest_path),
            "version": manifest["version"],
            "generator": manifest["generator"],
            "seed": manifest.get("seed"),
            "selected_images": len(selected_images),
            "total_images": len(manifest["images"]),
        },
        "metrics": aggregate(results, total_gt_lines),
        "warnings": warnings,
        "images": results,
    }
    if args.output:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(
            json.dumps(report, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
            newline="\n",
        )
    print(
        json.dumps(
            {"status": report["status"], "model": args.model_name, "metrics": report["metrics"]},
            ensure_ascii=False,
        )
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
